window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[275]={"id":"275","numero":275,"titre":"Splénomégalie","objectifs":[{"id":"275-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la splénomégalie","contenu":"<p>La <span class=\"kw-def\">splénomégalie</span> se définit comme une <span class=\"kw-def\">augmentation de la taille de la rate qui la rend palpable</span> à l'examen clinique — une rate de taille normale n'est jamais palpable. En cas de doute clinique (sujet obèse, <span class=\"kw-clinique\">ascite</span>), elle est confirmée par l'<span class=\"kw-imagerie\">imagerie abdominale</span>. <span class=\"kw-alerte\">Toute rate palpable est pathologique</span> et impose une exploration étiologique.</p>\n      <p><strong>Rappel anatomo-fonctionnel.</strong> La rate (<span class=\"kw-chiffre\">150-250 g</span>) siège dans l'<span class=\"kw-clinique\">hypochondre gauche</span>, en position thoraco-abdominale en regard de la <span class=\"kw-chiffre\">10ᵉ côte</span>, en dérivation entre la grande circulation et la circulation portale. Ses fonctions : organe hématopoïétique fœtal (<span class=\"kw-chiffre\">3ᵉ-5ᵉ mois</span> de vie intra-utérine, réactivable en pathologie) ; stockage d'environ <span class=\"kw-chiffre\">30 %</span> de la <span class=\"kw-clinique\">masse</span> plaquettaire ; filtre des hématies anormales ou à inclusions (<span class=\"kw-clinique\">corps de Howell-Joly</span>, parasites) ; organe lymphoïde périphérique synthétisant <span class=\"kw-clinique\">les</span> anticorps dirigés contre les germes encapsulés.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Mécanismes de la <span class=\"kw-clinique\">splénomégalie</span></h4>\n      <table >\n        <thead><tr><th>Mécanisme</th><th>Exemples</th></tr></thead>\n        <tbody>\n          <tr><td>Augmentation de la cellularité par accumulation</td><td>Accumulation de <span class=\"kw-bio\">lymphocytes</span> malins (<span class=\"kw-etio\">lymphomes</span>) ; accumulation de macrophages dans <span class=\"kw-clinique\">les</span> maladies de surcharge (<span class=\"kw-etio\">maladie de Gaucher</span>)</td></tr>\n          <tr><td><span class=\"kw-clinique\">Hypertension</span> portale</td><td>Toute cause d'augmentation de la pression dans le système porte</td></tr>\n          <tr><td>Séquestration splénique</td><td>Séquestration des globules rouges au cours des anémies hémolytiques (<span class=\"kw-etio\">sphérocytose héréditaire</span>)</td></tr>\n          <tr><td>Métaplasie myéloïde</td><td><span class=\"kw-etio\">Myélofibroses</span> primitives ou secondaires</td></tr>\n          <tr><td>Maladies granulomateuses</td><td><span class=\"kw-ttt\">Infiltration</span> granulomateuse du parenchyme splénique</td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Conséquences</h4>\n      <table >\n        <thead><tr><th>Conséquence</th><th>Mécanisme</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Hypersplénisme</span></td><td>Séquestration splénique anormale des globules rouges, des <span class=\"kw-bio\">leucocytes</span> et — surtout — des <span class=\"kw-bio\">plaquettes</span></td></tr>\n          <tr><td><span class=\"kw-alerte\">Hémodilution</span> (« fausse anémie »)</td><td>Inflation du volume plasmatique : <span class=\"kw-clinique\">masse</span> globulaire totale inchangée mais <span class=\"kw-bio\">hémoglobine</span> abaissée</td></tr>\n          <tr><td><span class=\"kw-clinique\">Hypertension</span> portale d'apport</td><td>Survient lorsque la rate est très volumineuse</td></tr>\n          <tr><td>Diminution des facteurs de coagulation</td><td>Baisse du <span class=\"kw-bio\">facteur V</span> et du <span class=\"kw-bio\">TP</span>, <span class=\"kw-alerte\">asymptomatique</span></td></tr>\n        </tbody>\n      </table>","frequence":3,"liens":[{"href":"https://cerf.radiologie.fr/sites/cerf.radiologie.fr/files/files/enseignement/pdf/04FP%20Anatomie%20Rate%20DES.pdf","label":"04fp anatomie rate des"},{"href":"https://radiopaedia.org/articles/splenic-infarction","label":"Radiopaedia : Splenic infarction"},{"href":"https://radiopaedia.org/articles/splenomegaly","label":"Radiopaedia : Splenomegaly"}]},{"id":"275-2","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic clinique d’une splénomégalie","contenu":"<p>Le diagnostic de <span class=\"kw-clinique\">splénomégalie</span> est <span class=\"kw-clinique\">essentiellement clinique</span>, par <span class=\"kw-clinique\">palpation</span>. La rate est le plus souvent indolore, mais peut entraîner une <span class=\"kw-clinique\">pesanteur ou une douleur de l'hypochondre gauche</span>, augmentée à l'<span class=\"kw-clinique\">inspiration profonde</span> et irradiant « <span class=\"kw-clinique\">en bretelle</span> » vers l'épaule gauche, ainsi qu'une gêne post-prandiale ou une <span class=\"kw-clinique\">constipation</span>.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Technique de palpation</h4>\n      <table >\n        <thead><tr><th>Étape</th><th>Modalité</th></tr></thead>\n        <tbody>\n          <tr><td>Position du patient</td><td><strong>Décubitus :</strong> dorsal, tête à l'horizontale, genoux fléchis, inspiration profonde <br><strong>Variante :</strong> décubitus latéral droit, bras gauche surélevé</td></tr>\n          <tr><td>Main palpatrice</td><td>Posée à plat en oblique ; recherche du bord inférieur de la rate en partant de la <span class=\"kw-clinique\">fosse iliaque gauche</span> et en remontant vers le rebord costal</td></tr>\n          <tr><td>Caractères de la rate</td><td><strong>Bord :</strong> antéro-interne <span class=\"kw-clinique\">crénelé</span> <br><strong>Percussion :</strong> <span class=\"kw-clinique\">masse</span> mate <br><strong><span class=\"kw-def\">Contact</span> lombaire :</strong> absent</td></tr>\n          <tr><td>Mesure de la taille</td><td><strong>Minime :</strong> <span class=\"kw-chiffre\">1-2 cm</span> entre la rate et le rebord costal <br><strong>Modérée :</strong> taille intermédiaire <br><strong>Massive :</strong> <span class=\"kw-chiffre\">&gt; 10 cm</span>, pouvant dépasser l'ombilic et occuper tout le flanc gauche</td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Diagnostics différentiels à la palpation de l'hypochondre gauche</h4>\n      <table >\n        <thead><tr><th>Entité</th><th>Caractères discriminants</th></tr></thead>\n        <tbody>\n          <tr><td>Hypertrophie du lobe hépatique gauche</td><td><span class=\"kw-clinique\">Masse</span> en continuité avec le foie</td></tr>\n          <tr><td>Gros rein gauche</td><td><strong>Position :</strong> postérieure <br><strong>Mobilité :</strong> immobile à l'inspiration profonde <br><strong><span class=\"kw-def\">Contact</span> lombaire :</strong> présent</td></tr>\n          <tr><td>Kyste ou tumeur de la queue du pancréas</td><td>Non mobile à l'inspiration</td></tr>\n          <tr><td>Tumeur digestive ou mésentérique</td><td>La tumeur de l'angle colique gauche est parfois antérieure, immobile, à bord antérieur non crénelé</td></tr>\n          <tr><td>Tumeur surrénale gauche</td><td><span class=\"kw-clinique\">Masse</span> de l'hypochondre gauche d'origine surrénalienne</td></tr>\n          <tr><td>Cancer gastrique</td><td>Non mobile à l'inspiration</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">📌 En cas de doute clinique (<span class=\"kw-etio\">obésité</span>, <span class=\"kw-clinique\">ascite</span>, <span class=\"kw-clinique\">masse</span> indéterminée), l'<span class=\"kw-imagerie\">échographie abdominale</span> confirme la <span class=\"kw-clinique\">splénomégalie</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 214 — Thrombopénie</em></p>","frequence":2},{"id":"275-3","rang":"A","rubrique":"Diagnostic positif","titre":"Identifier les signes cliniques évocateurs d’une hépatopathie","contenu":"<p>Devant une <span class=\"kw-clinique\">splénomégalie</span>, la recherche de <span class=\"kw-clinique\">signes d'hépatopathie</span> oriente vers une <span class=\"kw-etio\">cirrhose</span> avec <span class=\"kw-etio\">hypertension portale</span> — première cause de splénomégalie en Europe.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Signes cliniques évocateurs d'une hépatopathie</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Ictère</span> conjonctival ou cutané</li>\n        <li><span class=\"kw-clinique\">Hépatomégalie</span></li>\n        <li><span class=\"kw-clinique\">Ascite</span></li>\n        <li><span class=\"kw-clinique\">Circulation veineuse collatérale</span> abdominale</li>\n        <li><span class=\"kw-clinique\">Angiomes stellaires</span> et <span class=\"kw-clinique\">érythrose palmaire</span></li>\n        <li><span class=\"kw-clinique\">Astérixis</span> en cas d'<span class=\"kw-alerte\">encéphalopathie hépatique</span></li>\n      </ul>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Signes d'<span class=\"kw-clinique\">hypertension</span> portale</h4>\n      <ul>\n        <li>La <span class=\"kw-def\">splénomégalie</span> elle-même</li>\n        <li><span class=\"kw-clinique\">Ascite</span> et <span class=\"kw-clinique\">circulation veineuse collatérale</span></li>\n        <li><span class=\"kw-clinique\">Varices œsophagiennes</span> — à rechercher par <span class=\"kw-imagerie\">endoscopie œsogastrique</span> dans un second temps</li>\n      </ul>\n      <div class=\"callout callout-info\">📌 Devant une <span class=\"kw-clinique\">splénomégalie</span> avec signes d'hépatopathie, <span class=\"kw-clinique\">les</span> étiologies d'<span class=\"kw-etio\">hypertension portale</span> à évoquer sont la <span class=\"kw-etio\">cirrhose</span> (de loin la plus fréquente), la <span class=\"kw-etio\">thrombose de la veine porte</span>, le <span class=\"kw-etio\">syndrome de Budd-Chiari</span>, la <span class=\"kw-etio\">schistosomiase</span> et l'<span class=\"kw-etio\">insuffisance cardiaque droite</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 279 — Cirrhose · 213 — Anémie</em></p>","frequence":1},{"id":"275-4","rang":"A","rubrique":"Identifier une urgence","titre":"Identifier les signes d’un infarctus splénique","contenu":"<div class=\"callout callout-danger\">⚠️ <strong><span class=\"kw-alerte\">Urgence</span>.</strong> Une <span class=\"kw-alerte\">splénomégalie douloureuse</span> est un <span class=\"kw-alerte\">infarctus splénique jusqu'à preuve du contraire</span> — il survient sur des splénomégalies souvent volumineuses.</div>\n      <p>Habituellement indolore, la <span class=\"kw-clinique\">splénomégalie</span> peut devenir <span class=\"kw-clinique\">douloureuse</span> dans trois situations d'<span class=\"kw-alerte\">urgence</span>.</p>\n      <table >\n        <thead><tr><th>Entité</th><th>Mécanisme</th><th>Clinique</th><th>Imagerie &amp; <span class=\"kw-clinique\">évolution</span></th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-alerte\">Infarctus splénique</span></td>\n            <td><span class=\"kw-clinique\">Nécrose</span> <span class=\"kw-etio\">ischémique</span> sur <span class=\"kw-clinique\">splénomégalie</span> volumineuse</td>\n            <td><strong><span class=\"kw-clinique\">Fièvre</span> :</strong> fréquente (<span class=\"kw-chiffre\">38-38,5 °C</span>) <br><strong>Douleurs :</strong> flanc gauche ; hypochondre gauche ; basithoracique gauche ; scapulaire gauche <br><strong>Épanchement :</strong> pleural réactionnel</td>\n            <td><strong>Imagerie :</strong> <span class=\"kw-imagerie\">TDM &gt; échographie</span> <br><strong>Signe :</strong> <span class=\"kw-imagerie\">plages hypodenses triangulaires périphériques</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\">Rupture de rate</span></td>\n            <td>Exceptionnelle ; <span class=\"kw-clinique\">évolution</span> en deux temps</td>\n            <td><strong>1ᵉʳ temps :</strong> douleurs faisant rechercher un <span class=\"kw-alerte\">hématome sous-capsulaire</span> <br><strong>2ᵉ temps :</strong> tableau de <span class=\"kw-alerte\">choc hémorragique</span></td>\n            <td><strong>Imagerie :</strong> <span class=\"kw-imagerie\">échographie ou scanner</span> à la recherche de l'hématome sous-capsulaire</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\">Séquestration splénique</span></td>\n            <td>Séquestration aiguë massive d'hématies dans la rate</td>\n            <td><strong><span class=\"kw-def\">Terrain</span> :</strong> <span class=\"kw-etio\">drépanocytose</span>, surtout chez l'enfant <br><strong>Tableau :</strong> douleur splénique aiguë avec déglobulisation</td>\n            <td><span class=\"kw-alerte\">Urgence</span> transfusionnelle, pédiatrique avant tout</td>\n          </tr>\n        </tbody>\n      </table>","frequence":1},{"id":"275-5","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les principaux examens biologiques à réaliser en première intention devant une splénomégalie","contenu":"<p>Devant toute <span class=\"kw-clinique\">splénomégalie</span>, un <span class=\"kw-bio\">bilan biologique de première intention</span> est réalisé pour orienter le <span class=\"kw-def\">diagnostic étiologique</span>.</p>\n      <table >\n        <thead><tr><th>Examen</th><th>Cible diagnostique</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-bio\">NFS — frottis — réticulocytes</span></td>\n            <td><strong><span class=\"kw-bio\">NFS</span> :</strong> <span class=\"kw-bio\">thrombopénie</span> fréquente (jusqu'à <span class=\"kw-chiffre\">50 G/L</span>) ; <span class=\"kw-bio\">leucopénie</span> (<span class=\"kw-chiffre\">2-4 G/L</span>) ; <span class=\"kw-bio\">anémie</span> normocytaire parfois <br><strong>Frottis :</strong> cellules anormales ; <span class=\"kw-clinique\">corps de Howell-Joly</span> (post-splénectomie) <br><strong><span class=\"kw-bio\">Réticulocytes</span> :</strong> caractère <span class=\"kw-bio\">régénératif</span> (<span class=\"kw-chiffre\">100-180 G/L</span>) si composante hémolytique <br><strong>Cible :</strong> hémopathies ; hémolyses ; infections</td>\n          </tr>\n          <tr><td><span class=\"kw-bio\">Bilan hépatique</span> (γ-GT, transaminases, <span class=\"kw-bio\">PAL</span>, <span class=\"kw-bio\">TP</span>)</td><td><span class=\"kw-clinique\">Hypertension</span> portale ; cytolyse hépatique des infections virales</td></tr>\n          <tr><td><span class=\"kw-bio\">EPS / EPP</span> (électrophorèse des protides)</td><td><strong>Pic monoclonal :</strong> syndrome lymphoprolifératif <br><strong>Bloc β-γ :</strong> cirrhose <br><strong>Hypergammaglobulinémie :</strong> infection, maladie systémique</td></tr>\n          <tr><td>Marqueurs d'hémolyse (<span class=\"kw-bio\">bilirubine</span> totale et libre, <span class=\"kw-bio\">haptoglobine</span>, <span class=\"kw-bio\">LDH</span>, <span class=\"kw-bio\">test direct à l'antiglobuline</span>)</td><td>Recherche d'une hémolyse</td></tr>\n          <tr><td><span class=\"kw-bio\">CRP</span></td><td>Recherche d'un <span class=\"kw-clinique\">syndrome <span class=\"kw-etio\">inflammatoire</span></span></td></tr>\n          <tr><td><span class=\"kw-bio\">Bilan de coagulation</span></td><td>Insuffisance hépatocellulaire (baisse du <span class=\"kw-bio\">TP</span>) ; <span class=\"kw-clinique\">syndrome <span class=\"kw-etio\">inflammatoire</span></span> (baisse du <span class=\"kw-bio\">fibrinogène</span>)</td></tr>\n          <tr><td><span class=\"kw-bio\">Hémocultures</span> + recherche de <span class=\"kw-etio\">paludisme</span></td><td>D'emblée selon le contexte (<span class=\"kw-clinique\">fièvre</span>, séjour en zone d'endémie)</td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Autres anomalies de l'hémogramme orientant l'étiologie</h4>\n      <ul>\n        <li><span class=\"kw-bio\">Polynucléose neutrophile</span> → infection <span class=\"kw-etio\">bactérienne</span></li>\n        <li><span class=\"kw-bio\">Leucopénie</span> → infection <span class=\"kw-etio\">virale</span>, <span class=\"kw-clinique\">fièvre</span> typhoïde ou brucellose (prescrire <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">sérologies</span> adaptées)</li>\n        <li><span class=\"kw-bio\">Hyperlymphocytose</span> avec <span class=\"kw-bio\">lymphocytes</span> stimulés + angine fébrile → syndrome mononucléosique</li>\n        <li><span class=\"kw-bio\">Hyperlymphocytose chronique</span> après <span class=\"kw-chiffre\">40-50 ans</span> → syndrome lymphoprolifératif (immunophénotypage)</li>\n        <li><span class=\"kw-bio\">Cytopénies</span> + <span class=\"kw-bio\">cellules anormales</span> (blastes, tricholeucocytes) → myélogramme</li>\n        <li><span class=\"kw-bio\">Anémie régénérative</span> → hémolyse ; test direct à l'antiglobuline indispensable</li>\n        <li><span class=\"kw-bio\">Hémoglobine augmentée</span>, hyperleucocytose avec myélémie ou hyperplaquettose chronique → néoplasie myéloproliférative</li>\n      </ul>\n      <div class=\"callout callout-warn\">⚠️ Dans la <span class=\"kw-etio\">tuberculose des organes hématopoïétiques</span>, on peut observer une <span class=\"kw-bio\">pancytopénie</span> sans cellules anormales circulantes.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 213 — Anémie · 214 — Thrombopénie · 215 — <span class=\"kw-clinique\">Purpura</span> · 317 — Syndrome myéloprolifératif</em></p>","frequence":1},{"id":"275-6","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les principaux examens complémentaires (dont imagerie) pour orienter le diagnostic étiologique","contenu":"<p>En seconde intention, des examens d'<span class=\"kw-imagerie\">imagerie</span> et des examens ciblés orientent le <span class=\"kw-def\">diagnostic étiologique</span>.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Imagerie</h4>\n      <table >\n        <thead><tr><th>Modalité</th><th>Apport</th></tr></thead>\n        <tbody>\n          <tr><td>Indications de l'imagerie</td><td>Non indispensable pour confirmer la <span class=\"kw-clinique\">splénomégalie</span> ; utile en cas de doute ou de cas difficile ; mesure du volume splénique ; étude de la structure de la rate et des organes intra-abdominaux</td></tr>\n          <tr><td><span class=\"kw-imagerie\">Échographie</span> (1ʳᵉ intention)</td><td><strong>Dimensions :</strong> grand axe <span class=\"kw-chiffre\">12-14 cm</span> ; transverse <span class=\"kw-chiffre\">4-8 cm</span> ; antéro-postérieur <span class=\"kw-chiffre\">6-12 cm</span> <br><strong>Critère :</strong> <span class=\"kw-clinique\">splénomégalie</span> si <span class=\"kw-chiffre\">≥ 2/3</span> des dimensions sont anormales <br><strong>Doppler :</strong> flux portal, thrombose porte, veines sus-hépatiques</td></tr>\n          <tr><td><span class=\"kw-imagerie\">TDM abdominale</span></td><td>Perte de la concavité, de la densité et de l'homogénéité du parenchyme ; détection des <span class=\"kw-imagerie\">adénopathies profondes</span> et des masses associées</td></tr>\n          <tr><td>Sans intérêt diagnostique</td><td><span class=\"kw-imagerie\">ASP</span> ; explorations radiologiques vasculaires ; <span class=\"kw-imagerie\">TEP-FDG</span> au <span class=\"kw-def\">stade</span> diagnostique</td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Démarche étiologique au second temps</h4>\n      <p>Transcription du schéma « Démarche diagnostique devant une <span class=\"kw-clinique\">splénomégalie</span> » : après le bilan <span class=\"kw-ttt\">biologique</span> et radiologique, l'orientation initiale guide <span class=\"kw-clinique\">les</span> examens ciblés.</p>\n      <table >\n        <thead><tr><th>Orientation initiale</th><th>Examen ciblé</th></tr></thead>\n        <tbody>\n          <tr><td>Signes d'hépatopathie / <span class=\"kw-clinique\">hypertension</span> portale</td><td><span class=\"kw-imagerie\">Endoscopie œsogastrique</span> à la recherche de <span class=\"kw-clinique\">varices œsophagiennes</span></td></tr>\n          <tr><td>Signes généraux, anomalies de la <span class=\"kw-bio\">NFS</span>, <span class=\"kw-clinique\">adénopathies</span> profondes</td><td><span class=\"kw-imagerie\">Radiographie pulmonaire</span> ; <span class=\"kw-bio\">myélogramme / BOM</span> selon l'orientation</td></tr>\n          <tr><td><span class=\"kw-clinique\">Splénomégalie</span> isolée</td><td><span class=\"kw-bio\">Myélogramme / BOM</span> (<span class=\"kw-ttt\">infiltration</span> lymphomateuse, maladie de surcharge, <span class=\"kw-clinique\">splénomégalie</span> myéloïde, leucémie à tricholeucocytes)</td></tr>\n          <tr><td>Toutes <span class=\"kw-clinique\">les</span> invest<span class=\"kw-chiffre\">iga</span>tions négatives</td><td><span class=\"kw-bio\">Ponction-biopsie hépatique</span> (granulomatose hépatique, amylose, maladie de surcharge)</td></tr>\n          <tr><td>Diagnostic toujours non établi</td><td><span class=\"kw-alerte\">Splénectomie à visée diagnostique</span> — dernier recours, après discussion en <span class=\"kw-def\">RCP</span></td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Place de la splénectomie à visée diagnostique</h4>\n      <ul>\n        <li>Exploration complète de l'abdomen, <span class=\"kw-bio\">biopsie hépatique</span> et de toute <span class=\"kw-clinique\">adénopathie</span> intra-abdominale</li>\n        <li>Étude anatomopathologique de la pièce opératoire : lymphome splénique primitif, maladie de surcharge constitutionnelle, tumeur primitive</li>\n        <li>Fragment adressé en microbiologie pour cultures avec <span class=\"kw-bio\">recherche de mycobactéries</span></li>\n      </ul>","frequence":2},{"id":"275-7","rang":"B","rubrique":"Contenu multimédia","titre":"Coupe de tomodensitométrie abdominale avec splénomégalie","contenu":"<p>La <span class=\"kw-imagerie\">TDM abdomino-pelvienne avec injection au temps portal</span> confirme et quantifie l'<span class=\"kw-def\">augmentation du volume splénique</span>. La rate se mesure :</p>\n      <ul>\n        <li>en <span class=\"kw-radio\">coupe axiale</span> : grand axe — <strong><span class=\"kw-clinique\">splénomégalie</span> si &gt;<span class=\"kw-chiffre\"> 12 cm</span></strong> ;</li>\n        <li>en <span class=\"kw-radio\">coupe coronale</span> : grand axe (ou flèche) — <strong><span class=\"kw-clinique\">splénomégalie</span> si &gt;<span class=\"kw-chiffre\"> 12-13 cm</span></strong> ; ou hauteur vraie — <strong>splénomégalie si &gt;<span class=\"kw-chiffre\"> 10 cm</span></strong>.</li>\n      </ul>\n\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/275/tdm-splenomegalie.png\" alt=\"TDM abdomino-pelvienne avec injection au temps portal, coupes coronale et axiale, montrant une augmentation du volume splénique (splénomégalie)\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">TDM abdomino-pelvienne</span>, avec injection au temps portal (coupes <span class=\"kw-radio\">coronale</span> et <span class=\"kw-radio\">axiale</span>). <span class=\"kw-def\">Splénomégalie</span> : <span class=\"kw-radio\">augmentation du volume splénique</span>, mesurée &gt;<span class=\"kw-chiffre\"> 12 cm</span> en grand axe. Source : banque imagerie « Imagerie à connaître » (item 275).</figcaption>\n      </figure>","frequence":1},{"id":"275-8","rang":"A","rubrique":"Étiologies","titre":"Connaître les principales causes de splénomégalie (dont infections et hémopathies)","contenu":"<div class=\"callout callout-warn\">⚠️ <strong>À retenir.</strong> La cause la plus fréquente de <span class=\"kw-clinique\">splénomégalie</span> dans le <strong>monde</strong> est le <span class=\"kw-etio\">paludisme</span> ; en <strong>Europe</strong>, c'est l'<span class=\"kw-etio\">hypertension portale</span>.</div>\n      <p><span class=\"kw-clinique\">Les</span> causes de <span class=\"kw-clinique\">splénomégalie</span> se regroupent en cinq grandes familles étiologiques (les hémopathies font l'objet de l'objectif suivant).</p>\n      <table >\n        <thead><tr><th>Famille</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Hypertension portale</span></td><td><span class=\"kw-etio\">Cirrhose</span> (de loin la plus fréquente) ; <span class=\"kw-etio\">thrombose de la veine porte</span> ; <span class=\"kw-alerte\">syndrome de Budd-Chiari</span> ; compression <span class=\"kw-etio\">tumorale</span> intra-hépatique ; <span class=\"kw-etio\">hémochromatose</span> ; <span class=\"kw-etio\">sarcoïdose</span> ; <span class=\"kw-etio\">schistosomiase</span> (bilharziose) ; <span class=\"kw-etio\">insuffisance cardiaque droite</span></td></tr>\n          <tr><td>Infections</td><td><strong>Bactéries :</strong> <span class=\"kw-etio\">endocardite</span> (maladie d'Osler) ; septicémies ; <span class=\"kw-etio\">tuberculose</span> ; <span class=\"kw-clinique\">fièvre</span> typhoïde <br><strong>Virus :</strong> <span class=\"kw-etio\">VIH</span> ; <span class=\"kw-etio\">EBV</span> ; <span class=\"kw-etio\">CMV</span> ; <span class=\"kw-etio\">VZV</span> (rare) ; hépatites virales <br><strong>Parasites :</strong> <span class=\"kw-etio\">paludisme</span> ; leishmaniose viscérale (kala-azar) ; trypanosomiases <br><strong>Champignons :</strong> <span class=\"kw-etio\">candida</span></td></tr>\n          <tr><td>Hémolyse</td><td>Tableau associant <span class=\"kw-clinique\">ictère</span>, urines foncées, <span class=\"kw-bio\">anémie régénérative</span>, baisse de l'<span class=\"kw-bio\">haptoglobine</span>, élévation de la <span class=\"kw-bio\">bilirubine libre</span> et des <span class=\"kw-bio\">LDH</span> ; hémolyses chroniques corpusculaires et extra-corpusculaires</td></tr>\n          <tr><td>Maladies systémiques</td><td><span class=\"kw-etio\">Lupus</span> ; <span class=\"kw-etio\">sarcoïdose</span> ; polyarthrite <span class=\"kw-etio\">inflammatoire</span> ; maladie périodique ; <span class=\"kw-etio\">syndrome de Felty</span> ; maladie de Still ; <span class=\"kw-clinique\">fièvre</span> familiale méditerranéenne</td></tr>\n          <tr><td>Autres causes</td><td><strong>Maladies de surcharge :</strong> <span class=\"kw-etio\">maladie de Gaucher</span> ; <span class=\"kw-etio\">maladie de Niemann-Pick</span> <br><strong>Tumeurs &amp; divers :</strong> métastase de tumeur solide ; traumatisme ; kystes ; hémangiome</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 169 — <span class=\"kw-etio\">VIH</span> · 170 — <span class=\"kw-clinique\">Paludisme</span> · 152 — <span class=\"kw-clinique\">Endocardite</span> infectieuse · 217 — Syndrome mononucléosique · 194 — <span class=\"kw-clinique\">Lupus</span> - SAPL · 195 — Artérite à cellules géantes · 211 — Sarcoïdose · 279 — Cirrhose</em></p>","frequence":3},{"id":"275-9","rang":"A","rubrique":"Étiologies","titre":"Connaître les principales hémopathies responsables d’une splénomégalie","contenu":"<p>La <strong>plupart des hémopathies malignes</strong> peuvent être responsables d'une <span class=\"kw-clinique\">splénomégalie</span>. On <span class=\"kw-clinique\">les</span> répartit en deux grandes familles.</p>\n      <table >\n        <thead><tr><th>Famille</th><th>Hémopathies</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Syndromes myéloprolifératifs</span></td><td><strong>SMP classiques :</strong> maladie de <span class=\"kw-etio\">Vaquez</span> ; <span class=\"kw-etio\">thrombocytémie essentielle</span> ; <span class=\"kw-etio\">myélofibrose primitive</span> (= <span class=\"kw-clinique\">splénomégalie</span> myéloïde) ; <span class=\"kw-etio\">LMC</span> <br><strong>Apparenté :</strong> <span class=\"kw-etio\">LMMC</span> (leucémie myélomonocytaire chronique)</td></tr>\n          <tr><td>Hémopathies lymphoïdes</td><td><strong>Lymphomes :</strong> maladie de <span class=\"kw-etio\">Hodgkin</span> ; lymphomes <span class=\"kw-etio\">non hodgkiniens</span> <br><strong>Leucémies :</strong> <span class=\"kw-etio\">LLC</span> ; <span class=\"kw-etio\">LAL</span> <br><strong>Autres :</strong> maladie de <span class=\"kw-etio\">Waldenström</span> ; leucémie à <span class=\"kw-etio\">tricholeucocytes</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">⚠️ <strong>Pièges classiques.</strong> Le <span class=\"kw-alerte\">myélome ne donne jamais de splénomégalie</span>. <span class=\"kw-clinique\">Les</span> <span class=\"kw-alerte\">SMD</span> et la <span class=\"kw-alerte\">LAM</span> en donnent rarement (plutôt la LMMC et la LAL).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 315 — Leucémie aiguë · 317 — Syndrome myéloprolifératif · 318 — Leucémie lymphoïde chronique · 319 — Lymphome malin</em></p>","frequence":2},{"id":"275-10","rang":"B","rubrique":"Prise en charge","titre":"Connaître les mesures prophylactiques avant splénectomie","contenu":"<div class=\"callout callout-danger\">⚠️ <strong>OPSI.</strong> La splénectomie expose à des <span class=\"kw-alerte\">infections fulminantes</span> (<em>overwhelming post-splenectomy infection</em>) — <span class=\"kw-alerte\">sepsis</span>, <span class=\"kw-alerte\">méningites</span> — surtout à <span class=\"kw-etio\">germes encapsulés</span> : <span class=\"kw-etio\">méningocoque</span>, <span class=\"kw-etio\">pneumocoque</span>, <span class=\"kw-etio\">Haemophilus influenzae</span>.</div>\n      <p>La prophylaxie péri-splénectomie associe une <span class=\"kw-ttt\">mise à jour vaccinale</span> et une <span class=\"kw-ttt\">antibioprophylaxie</span>.</p>\n      <table >\n        <thead><tr><th>Phase</th><th>Mesures</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Avant</strong> la splénectomie<br>(<span class=\"kw-chiffre\">≥ 2 semaines</span> avant si programmée ; sinon <span class=\"kw-chiffre\">2 semaines</span> après)</td>\n            <td><strong><span class=\"kw-ttt\">Calendrier vaccinal</span> :</strong> mise à jour systématique <br><strong><span class=\"kw-etio\">Pneumocoque</span> :</strong> 1 dose de VPC13 puis, <span class=\"kw-chiffre\">2 mois</span> après, 1 dose de VPP23, avec rappel VPP23 tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">5 ans</span> — <em>ou</em> <span class=\"kw-ttt\">Prevenar 20</span> (2024) en <span class=\"kw-chiffre\">1 seule injection</span> <br><strong><span class=\"kw-etio\">Méningocoque</span> :</strong> ACYW = <span class=\"kw-chiffre\">2 injections</span> à <span class=\"kw-chiffre\">6 mois</span> d'intervalle + rappel tous les <span class=\"kw-chiffre\">5 ans</span> ; B = <span class=\"kw-chiffre\">2 injections</span> à <span class=\"kw-chiffre\">1 mois</span> d'intervalle, sans rappel <br><strong><span class=\"kw-etio\">Haemophilus</span> influenzae B :</strong> 1 dose <br><strong><span class=\"kw-etio\">Grippe</span> :</strong> <span class=\"kw-ttt\">vaccination</span> annuelle</td>\n          </tr>\n          <tr>\n            <td><strong>Après</strong> la splénectomie</td>\n            <td><strong><span class=\"kw-ttt\">Antibioprophylaxie</span> :</strong> <span class=\"kw-ttt\">pénicilline V</span> (oracilline) au long cours — <span class=\"kw-chiffre\">≥ 2 ans</span> chez l'adulte, <span class=\"kw-chiffre\">≥ 5 ans</span> chez l'enfant (jusqu'à l'adolescence selon l'avis hématologique) <br><strong>Vaccins :</strong> rattrapage <span class=\"kw-chiffre\">2 semaines</span> après l'intervention si non faits avant <br><strong>Vaccins vivants :</strong> aucune <span class=\"kw-ci\">contre-indication</span> chez le splénectomisé</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">⚠️ <strong><span class=\"kw-clinique\">Fièvre</span> = <span class=\"kw-alerte\">urgence</span> absolue.</strong> Toute <span class=\"kw-alerte\">fièvre inexpliquée</span> chez un splénectomisé (ou un asplénique fonctionnel) impose une <span class=\"kw-ttt\">antibiothérapie probabiliste</span> après <span class=\"kw-bio\">hémocultures</span> : <span class=\"kw-ttt\">C3G parentérale</span> (<span class=\"kw-ttt\">céfotaxime</span> ou <span class=\"kw-ttt\">ceftriaxone</span>) couvrant <span class=\"kw-clinique\">les</span> germes encapsulés. La <span class=\"kw-ttt\">vaccination</span> anti-pneumococcique n'élimine pas le risque d'infection à <span class=\"kw-etio\">pneumocoque</span>. La gravité est majorée en cas d'infection par <span class=\"kw-etio\">Plasmodium</span> (protozoaire intracellulaire).</div>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"kw-bio\">NFS</span> après splénectomie</h4>\n      <ul>\n        <li>Pendant quelques semaines : <span class=\"kw-bio\">hyperleucocytose</span> modérée (<span class=\"kw-chiffre\">10-15 G/L</span>) et <span class=\"kw-bio\">hyperplaquettose</span> transitoires, parfois durables</li>\n        <li>À vie : hématies à <span class=\"kw-clinique\">corps de Howell-Joly</span></li>\n        <li>Parfois : discrète <span class=\"kw-bio\">thrombocytose</span> et autres anomalies morphologiques des hématies</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 146 — <span class=\"kw-ttt\">Vaccination</span> · 152 — <span class=\"kw-clinique\">Endocardite</span> infectieuse · 170 — <span class=\"kw-clinique\">Paludisme</span></em></p>","frequence":2}],"astuces":[],"strategie":{"urgence":"<p>Habituellement indolore, une <span class=\"kw-clinique\">splénomégalie</span> devenue <span class=\"kw-clinique\">douloureuse</span> est un <span class=\"kw-alerte\">infarctus splénique jusqu'à preuve du contraire</span> — trois situations aiguës à reconnaître.</p><p><strong><span class=\"kw-clinique\">Infarctus</span> splénique</strong></p><p><span class=\"kw-imagerie\">TDM</span> &gt; <span class=\"kw-imagerie\">échographie</span> : <span class=\"kw-imagerie\">plages hypodenses triangulaires périphériques</span></p><ul><li>Survient sur une <span class=\"kw-clinique\">splénomégalie volumineuse</span> ; <span class=\"kw-clinique\">fièvre</span> fréquente (<span class=\"kw-chiffre\">38–38,5 °C</span>)</li><li>Douleurs du <span class=\"kw-clinique\">flanc gauche</span>, de l'<span class=\"kw-clinique\">hypochondre gauche</span>, <span class=\"kw-clinique\">basithoraciques</span> et <span class=\"kw-clinique\">scapulaires gauches</span> ; <span class=\"kw-clinique\">épanchement pleural</span> réactionnel</li></ul><p><strong><span class=\"kw-alerte\">Rupture</span> de rate <span class=\"q\">— <span class=\"kw-clinique\">évolution</span> en deux temps</span></strong></p><p><span class=\"kw-imagerie\">échographie</span> ou <span class=\"kw-imagerie\">scanner</span> en <span class=\"kw-alerte\">urgence</span> (hématome sous-capsulaire)</p><ul><li>Exceptionnelle ; 1ᵉʳ temps : douleurs faisant rechercher un <span class=\"kw-alerte\">hématome sous-capsulaire</span></li><li>2ᵉ temps : <span class=\"kw-alerte\">choc hémorragique</span></li></ul><p><strong>Séquestration splénique aiguë</strong></p><p><span class=\"kw-alerte\">urgence transfusionnelle</span> pédiatrique</p><ul><li><span class=\"kw-def\">Terrain</span> : <span class=\"kw-etio\">drépanocytose</span>, surtout chez l'<span class=\"kw-clinique\">enfant</span></li><li>Douleur splénique aiguë avec <span class=\"kw-alerte\">déglobulisation</span></li></ul>","redflags":"<ul><li><span class=\"kw-alerte\">Splénomégalie douloureuse</span> → <span class=\"kw-def\">infarctus splénique</span> jusqu'à preuve du contraire</li><li><span class=\"kw-alerte\">Choc hémorragique</span> après des douleurs en deux temps → <span class=\"kw-def\">rupture de rate</span></li><li>Chez le <span class=\"kw-etio\">drépanocytaire</span> (enfant) : douleur splénique aiguë avec <span class=\"kw-alerte\">déglobulisation</span> → <span class=\"kw-def\">séquestration splénique aiguë</span></li><li><span class=\"kw-alerte\">Fièvre inexpliquée</span> chez un <span class=\"kw-clinique\">splénectomisé</span> (ou asplénique fonctionnel) → <span class=\"kw-def\">OPSI</span> (<span class=\"kw-alerte\">sepsis</span> fulminant à <span class=\"kw-etio\">germes encapsulés</span>), gravité majorée si <span class=\"kw-etio\">paludisme</span></li></ul>","principes":"<p>La prise en charge est avant tout <strong>étiologique</strong> : <span class=\"kw-alerte\">toute rate palpable est pathologique</span> et impose une exploration. La <span class=\"kw-ttt\">splénectomie</span> (à visée diagnostique ou thérapeutique) est un dernier recours qui impose une <span class=\"kw-ttt\">prophylaxie anti-OPSI</span>.</p><p><strong>Traitement étiologique</strong></p><ul><li>Traiter la cause : <span class=\"kw-etio\">hypertension portale</span> / <span class=\"kw-etio\">cirrhose</span>, <span class=\"kw-etio\">infection</span>, <span class=\"kw-etio\">hémopathie</span>, <span class=\"kw-etio\">hémolyse</span>…</li><li>L'<span class=\"kw-clinique\">hypersplénisme</span> (cytopénies) régresse avec le traitement de la cause</li></ul><p><strong>Splénectomie à visée diagnostique <span class=\"q\">— dernier recours</span></strong></p><ul><li>Indiquée si <span class=\"kw-clinique\">splénomégalie importante symptomatique</span> sans diagnostic établi, après <span class=\"kw-ttt\">discussion en RCP</span></li><li>Exploration complète de l'abdomen + <span class=\"kw-bio\">biopsie hépatique</span> et de toute <span class=\"kw-bio\">adénopathie</span> ; fragment en microbiologie (<span class=\"kw-bio\">recherche de mycobactéries</span>)</li></ul><p><strong>Prophylaxie péri-splénectomie (anti-OPSI)</strong></p><p>la <span class=\"kw-ttt\">vaccination</span> anti-pneumococcique n'élimine pas le risque d'infection à <span class=\"kw-etio\">pneumocoque</span></p><ul><li>Vaccins <span class=\"kw-chiffre\">≥ 2 semaines</span> avant (ou <span class=\"kw-chiffre\">2 semaines</span> après si non programmée) : <span class=\"kw-ttt\">anti-pneumocoque</span> (VPC13 puis VPP23, ou <span class=\"kw-ttt\">Prevenar 20</span> en 1 injection), <span class=\"kw-ttt\">anti-méningocoque</span> ACYW + B, <span class=\"kw-ttt\">anti-Haemophilus influenzae b</span>, <span class=\"kw-ttt\">grippe</span> annuelle</li><li><span class=\"kw-ttt\">Antibioprophylaxie</span> par <span class=\"kw-ttt\">pénicilline V</span> au long cours : <span class=\"kw-chiffre\">≥ 2 ans</span> (adulte), <span class=\"kw-chiffre\">≥ 5 ans</span> (enfant)</li><li>Aucune <span class=\"kw-ci\">contre-indication aux vaccins vivants</span> chez le splénectomisé</li></ul><p><strong><span class=\"kw-clinique\">Fièvre</span> chez le splénectomisé <span class=\"q\">— <span class=\"kw-alerte\">urgence</span> absolue</span></strong></p><p>gravité majorée en cas d'infection à <span class=\"kw-etio\">Plasmodium</span> (protozoaire intracellulaire)</p><ul><li><span class=\"kw-ttt\">Antibiothérapie probabiliste</span> active sur <span class=\"kw-clinique\">les</span> <span class=\"kw-etio\">germes encapsulés</span>, débutée après <span class=\"kw-bio\">hémocultures</span></li><li><span class=\"kw-ttt\">C3G parentérale</span> (<span class=\"kw-ttt\">céfotaxime</span> ou <span class=\"kw-ttt\">ceftriaxone</span>), puis adaptation secondaire</li></ul>","suivi":"<p><strong><span class=\"kw-bio\">NFS</span> post-splénectomie :</strong> <span class=\"kw-bio\">hyperleucocytose</span> modérée (<span class=\"kw-chiffre\">10–15 G/L</span>) et <span class=\"kw-bio\">hyperplaquettose</span> transitoires <span class=\"kw-clinique\">les</span> premières semaines ; à vie, hématies à <span class=\"kw-clinique\">corps de Howell-Joly</span>.<br><strong>Au long cours :</strong> éducation du patient asplénique — <span class=\"kw-alerte\">toute fièvre = urgence</span>, observance de l'<span class=\"kw-ttt\">antibioprophylaxie</span> et des <span class=\"kw-ttt\">rappels vaccinaux</span> (VPP23 / <span class=\"kw-etio\">méningocoque</span> ACYW tous les <span class=\"kw-chiffre\">5 ans</span>).<br><strong><span class=\"kw-clinique\">Splénomégalie</span> non opérée :</strong> <span class=\"kw-def\">surveillance</span> orientée par l'<span class=\"kw-etio\">étiologie</span>.</p>"},"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Splénomégalie : douleur aiguë (infarctus / rupture / séquestration) ? — Habituellement indolore — toute rate douloureuse est une urgence","detail":"<h4>CAT — devant une <span class=\"kw-clinique\">splénomégalie</span> — Écarter d'abord une douleur aiguë, puis dérouler la démarche étiologique</h4>","branches":[{"to":"q-douleur","label":"Oui — splénomégalie douloureuse","color":"red"},{"to":"q-orientation","label":"Non — splénomégalie indolore","color":"blue"}]},{"id":"q-douleur","kind":"decision","label":"Tableau clinique dominant ? — Trois situations d'urgence","branches":[{"to":"t-rupture","label":"Douleurs en 2 temps puis choc hémorragique","color":"red"},{"to":"t-infarctus","label":"Fièvre + douleurs, rate volumineuse","color":"red"},{"to":"t-sequestration","label":"Drépanocytaire (enfant) + déglobulisation","color":"red"}]},{"id":"t-rupture","kind":"terminal","label":"Rupture de rate","color":"red","detail":"<h4>Mécanisme</h4><ul><li>Exceptionnelle ; <span class=\"kw-clinique\">évolution</span> en <span class=\"kw-def\">deux temps</span></li></ul><h4>Clinique</h4><ul><li>1ᵉʳ temps : douleurs faisant rechercher un <span class=\"kw-alerte\">hématome sous-capsulaire</span></li><li>2ᵉ temps : <span class=\"kw-alerte\">choc hémorragique</span></li></ul><h4>Imagerie</h4><ul><li><span class=\"kw-imagerie\">échographie</span> ou <span class=\"kw-imagerie\">scanner</span> en <span class=\"kw-alerte\">urgence</span> (hématome sous-capsulaire)</li></ul>"},{"id":"t-infarctus","kind":"terminal","label":"Infarctus splénique","color":"red","detail":"<h4>Mécanisme</h4><ul><li><span class=\"kw-clinique\">Nécrose</span> <span class=\"kw-etio\">ischémique</span> sur <span class=\"kw-clinique\">splénomégalie volumineuse</span> ; une <span class=\"kw-alerte\">splénomégalie douloureuse</span> est un <span class=\"kw-clinique\">infarctus</span> jusqu'à preuve du contraire</li></ul><h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Fièvre</span> fréquente (<span class=\"kw-chiffre\">38–38,5 °C</span>)</li><li>Douleurs : <span class=\"kw-clinique\">flanc gauche</span>, <span class=\"kw-clinique\">hypochondre gauche</span>, <span class=\"kw-clinique\">basithoracique</span> et <span class=\"kw-clinique\">scapulaire gauches</span></li><li><span class=\"kw-clinique\">Épanchement pleural</span> réactionnel</li></ul><h4>Imagerie</h4><ul><li><span class=\"kw-imagerie\">TDM</span> &gt; <span class=\"kw-imagerie\">échographie</span> : <span class=\"kw-imagerie\">plages hypodenses triangulaires périphériques</span></li></ul>"},{"id":"t-sequestration","kind":"terminal","label":"Séquestration splénique aiguë","color":"red","detail":"<h4><span class=\"kw-def\">Terrain</span></h4><ul><li><span class=\"kw-etio\">Drépanocytose</span>, surtout chez l'<span class=\"kw-clinique\">enfant</span></li></ul><h4>Tableau</h4><ul><li>Douleur splénique aiguë avec <span class=\"kw-alerte\">déglobulisation</span> (séquestration aiguë d'hématies)</li></ul><h4>Conduite</h4><ul><li><span class=\"kw-alerte\">Urgence transfusionnelle</span>, avant tout pédiatrique</li></ul>"},{"id":"q-orientation","kind":"decision","label":"Orientation après examen clinique + bilan biologique de 1ʳᵉ intention ? — NFS-frottis-réticulocytes, bilan hépatique, EPP, marqueurs d'hémolyse, CRP, hémocultures ± paludisme","branches":[{"to":"t-htp","label":"Signes d'hépatopathie / HTP","color":"blue"},{"to":"t-infection","label":"Contexte infectieux","color":"amber"},{"to":"q-hemato","label":"Anomalies NFS / adénopathies","color":"amber"},{"to":"q-isolee","label":"Splénomégalie isolée, bilan négatif","color":"amber"}]},{"id":"t-htp","kind":"terminal","label":"Hypertension portale (cirrhose ++)","color":"blue","detail":"<h4>Signes d'hépatopathie / <span class=\"kw-clinique\">HTP</span></h4><ul><li><span class=\"kw-clinique\">Ictère</span>, <span class=\"kw-clinique\">hépatomégalie</span>, <span class=\"kw-clinique\">ascite</span>, <span class=\"kw-clinique\">circulation veineuse collatérale</span></li><li><span class=\"kw-clinique\">Angiomes stellaires</span>, <span class=\"kw-clinique\">érythrose palmaire</span></li></ul><h4>Étiologies</h4><ul><li><span class=\"kw-etio\">Cirrhose</span> (de loin la plus fréquente — 1ʳᵉ cause en Europe)</li><li><span class=\"kw-etio\">Thrombose de la veine porte</span>, <span class=\"kw-etio\">syndrome de Budd-Chiari</span>, compression <span class=\"kw-etio\">tumorale</span> intra-hépatique</li><li><span class=\"kw-etio\">Hémochromatose</span>, <span class=\"kw-etio\">sarcoïdose</span>, <span class=\"kw-etio\">schistosomiase</span>, <span class=\"kw-etio\">insuffisance cardiaque droite</span></li></ul><h4>Examen ciblé</h4><ul><li><span class=\"kw-imagerie\">Endoscopie œsogastrique</span> à la recherche de <span class=\"kw-clinique\">varices œsophagiennes</span></li></ul><h4>Renvoi</h4><ul><li>Item 279 (cirrhose)</li></ul>"},{"id":"t-infection","kind":"terminal","label":"Cause infectieuse","color":"amber","detail":"<h4>À retenir</h4><ul><li>Le <span class=\"kw-etio\">paludisme</span> est la 1ʳᵉ cause de <span class=\"kw-clinique\">splénomégalie</span> dans le monde</li></ul><h4>Étiologies</h4><ul><li><strong>Bactéries :</strong> <span class=\"kw-etio\">endocardite</span> (Osler), septicémies, <span class=\"kw-etio\">tuberculose</span>, <span class=\"kw-clinique\">fièvre</span> typhoïde</li><li><strong>Virus :</strong> <span class=\"kw-etio\">VIH</span>, <span class=\"kw-etio\">EBV</span>, <span class=\"kw-etio\">CMV</span>, hépatites virales</li><li><strong>Parasites :</strong> <span class=\"kw-etio\">paludisme</span>, leishmaniose viscérale, trypanosomiases</li><li><strong>Champignons :</strong> <span class=\"kw-etio\">candida</span></li></ul><h4>Bilan ciblé</h4><ul><li><span class=\"kw-bio\">Hémocultures</span>, <span class=\"kw-bio\">recherche de paludisme</span> (frottis / <span class=\"kw-bio\">goutte épaisse</span>), <span class=\"kw-bio\">sérologies</span> orientées</li></ul><h4>Renvoi</h4><ul><li>Item 170 (<span class=\"kw-clinique\">paludisme</span>) · Item 169 (<span class=\"kw-etio\">VIH</span>) · Item 152 (<span class=\"kw-clinique\">endocardite</span>) · Item 217 (syndrome mononucléosique)</li></ul>"},{"id":"q-hemato","kind":"decision","label":"Que montre l'hémogramme ? — Réticulocytes, frottis, immunophénotypage","branches":[{"to":"t-hemolyse","label":"Anémie régénérative + bilan d'hémolyse positif","color":"amber"},{"to":"t-hemopathie","label":"Cytopénies / cellules anormales / lymphocytose chronique","color":"amber"}]},{"id":"t-hemolyse","kind":"terminal","label":"Hémolyse","color":"amber","detail":"<h4>Confirmation</h4><ul><li><span class=\"kw-clinique\">Ictère</span>, urines foncées, <span class=\"kw-bio\">anémie régénérative</span>, <span class=\"kw-bio\">haptoglobine ↓</span>, <span class=\"kw-bio\">bilirubine libre ↑</span>, <span class=\"kw-bio\">LDH ↑</span></li></ul><h4>Mécanisme</h4><ul><li>Hémolyse chronique <span class=\"kw-etio\">corpusculaire</span> ou <span class=\"kw-etio\">extra-corpusculaire</span> ; séquestration splénique</li></ul><h4>Bilan</h4><ul><li><span class=\"kw-bio\">Test direct à l'antiglobuline</span> (Coombs) indispensable</li></ul><h4>Renvoi</h4><ul><li>Item 213 (anémie)</li></ul>"},{"id":"t-hemopathie","kind":"terminal","label":"Hémopathie maligne","color":"amber","detail":"<h4>Syndromes myéloprolifératifs</h4><ul><li><span class=\"kw-etio\">Vaquez</span>, <span class=\"kw-etio\">thrombocytémie essentielle</span></li><li><span class=\"kw-etio\">Myélofibrose</span> (<span class=\"kw-clinique\">splénomégalie</span> myéloïde), <span class=\"kw-etio\">LMC</span>, <span class=\"kw-etio\">LMMC</span></li></ul><h4>Hémopathies lymphoïdes</h4><ul><li>Lymphomes (<span class=\"kw-etio\">Hodgkin</span> / <span class=\"kw-etio\">non hodgkiniens</span>), <span class=\"kw-etio\">LLC</span>, <span class=\"kw-etio\">LAL</span></li><li><span class=\"kw-etio\">Waldenström</span>, leucémie à <span class=\"kw-etio\">tricholeucocytes</span></li></ul><h4>Piège</h4><ul><li>Le <span class=\"kw-alerte\">myélome ne donne jamais de splénomégalie</span> ; <span class=\"kw-alerte\">SMD</span> et <span class=\"kw-alerte\">LAM</span> rarement</li></ul><h4>Bilan</h4><ul><li><span class=\"kw-bio\">Myélogramme / BOM</span>, <span class=\"kw-bio\">immunophénotypage</span> du sang</li></ul><h4>Renvoi</h4><ul><li>Item 317 (SMP) · Item 318 (LLC) · Item 319 (lymphome) · Item 315 (leucémie aiguë)</li></ul>"},{"id":"q-isolee","kind":"decision","label":"Bilan de 2ᵉ intention ? — Myélogramme / BOM, puis ponction-biopsie hépatique","branches":[{"to":"t-isolee-dg","label":"Myélogramme/BOM ou PBH contributif","color":"amber"},{"to":"t-splenectomie","label":"Toutes investigations négatives","color":"amber"}]},{"id":"t-isolee-dg","kind":"terminal","label":"Diagnostic posé au 2ᵉ temps","color":"amber","detail":"<h4>Myélogramme / <span class=\"kw-imagerie\">BOM</span></h4><ul><li><span class=\"kw-ttt\">Infiltration</span> <span class=\"kw-etio\">lymphomateuse</span>, <span class=\"kw-etio\">maladie de surcharge</span>, <span class=\"kw-etio\">splénomégalie myéloïde</span>, leucémie à <span class=\"kw-etio\">tricholeucocytes</span></li></ul><h4>Si bilan négatif</h4><ul><li><span class=\"kw-bio\">Ponction-biopsie hépatique</span> : <span class=\"kw-etio\">granulomatose hépatique</span>, <span class=\"kw-etio\">amylose</span>, <span class=\"kw-etio\">maladie de surcharge</span></li></ul>"},{"id":"t-splenectomie","kind":"terminal","label":"Splénectomie à visée diagnostique","color":"amber","detail":"<h4>Indication</h4><ul><li>Diagnostic non établi malgré tout le bilan + <span class=\"kw-clinique\">splénomégalie importante symptomatique</span> ; dernier recours après <span class=\"kw-ttt\">discussion en RCP</span></li></ul><h4>Geste</h4><ul><li>Exploration complète de l'abdomen + <span class=\"kw-bio\">biopsie hépatique</span> et de toute <span class=\"kw-bio\">adénopathie</span> ; fragment en microbiologie (<span class=\"kw-bio\">recherche de mycobactéries</span>)</li></ul><h4>Prophylaxie anti-OPSI</h4><ul><li>Vaccins anti-<span class=\"kw-etio\">germes encapsulés</span> <span class=\"kw-chiffre\">≥ 2 semaines</span> avant + <span class=\"kw-ttt\">antibioprophylaxie</span> par <span class=\"kw-ttt\">pénicilline V</span></li></ul><h4>Renvoi</h4><ul><li>Item 146 (<span class=\"kw-ttt\">vaccination</span>)</li></ul>"}]},"cards":[{"i":"04e2c610f2db","n":275,"o":"275-1","u":"Définition","t":"Connaître la définition de la splénomégalie","q":"Comment définit-on cliniquement la splénomégalie et quelle est sa signification ?","a":"<p>La splénomégalie est définie par une augmentation de la taille de la rate, la rendant <strong>palpable</strong> à l'examen clinique. Toute rate palpable est pathologique et doit être explorée.</p>"},{"i":"239dd9238fee","n":275,"o":"275-1","u":"Définition","t":"Connaître la définition de la splénomégalie","q":"Quels mécanismes principaux peuvent entraîner une splénomégalie pathologique ?","a":"<ul><li>Augmentation de la cellularité par accumulation (lymphomes, maladies de surcharge comme la <strong>maladie de Gaucher</strong>).</li><li><strong>Hypertension portale</strong> de toute origine.</li><li>Séquestration splénique (par exemple, lors des <strong>anémies hémolytiques</strong> comme la sphérocytose héréditaire).</li><li>Métaplasie myéloïde (comme dans les <strong>myélofibroses</strong>).</li><li>Maladies granulomateuses avec infiltration du parenchyme splénique.</li></ul>"},{"i":"74add030ca9a","n":275,"o":"275-1","u":"Définition","t":"Connaître la définition de la splénomégalie","q":"Quelles sont les conséquences cliniques et biologiques de la splénomégalie ?","a":"<ul><li><strong>Hypersplénisme</strong> : séquestration anormale des globules rouges, des leucocytes et surtout des plaquettes.</li><li><strong>Hémodilution</strong> (« fausse anémie ») : inflation du volume plasmatique.</li><li>Hypertension portale d'apport, si la rate est très volumineuse.</li><li>Diminution asymptomatique des <strong>facteurs de coagulation</strong> (facteur V et TP).</li></ul>"},{"i":"9fd27f2160ab","n":275,"o":"275-1","u":"Définition","t":"Connaître la définition de la splénomégalie","q":"Dans quels cas la splénomégalie nécessite-t-elle une confirmation par imagerie abdominale ?","a":"<p>En cas de doute clinique (par exemple, chez un sujet <strong>obèse</strong> ou en présence d'une <strong>ascite</strong>), l'imagerie abdominale est nécessaire pour confirmer la splénomégalie.</p>"},{"i":"c5ba8146a23d","n":275,"o":"275-1","u":"Définition","t":"Connaître la définition de la splénomégalie","q":"Quelles sont les principales fonctions de la rate sur le plan hématologique et immunitaire ?","a":"<ul><li>Organe hématopoïétique fœtal (3<sup>e</sup>-5<sup>e</sup> mois de vie intra-utérine).</li><li>Stockage d'environ <strong>30 % de la masse plaquettaire</strong>.</li><li>Filtre des <strong>hématies anormales</strong> ou à inclusions (corps de Howell-Joly, parasites).</li><li>Organe lymphoïde périphérique synthétisant les <strong>anticorps</strong> dirigés contre les germes encapsulés.</li></ul>"},{"i":"0fcd03f1fc37","n":275,"o":"275-2","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic clinique d’une splénomégalie","q":"Comment doit-on positionner un patient pour réaliser une palpation de la rate à la recherche d'une splénomégalie ?","a":"<p>Le patient doit être en <strong>décubitus dorsal</strong>, tête à l'horizontale, <strong>genoux fléchis</strong>. On lui demande de réaliser une <strong>inspiration profonde</strong>. Une variante est le décubitus latéral droit, bras gauche surélevé.</p>"},{"i":"6816ef54c199","n":275,"o":"275-2","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic clinique d’une splénomégalie","q":"Quelle technique de palpation doit-on utiliser pour évaluer la rate en cas de suspicion de splénomégalie ?","a":"<p>La <strong>main palpatrice est posée à plat en oblique</strong>. Le clinicien recherche le bord inférieur de la rate en partant de la <strong>fosse iliaque gauche</strong> et en <strong>remontant vers le rebord costal</strong>, idéalement en fin d'inspiration.</p>"},{"i":"bb2ea9179e02","n":275,"o":"275-2","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic clinique d’une splénomégalie","q":"Quand faut-il faire une échographie abdominale pour confirmer une splénomégalie ?","a":"<p>L'échographie abdominale est indiquée en cas de <strong>doute clinique</strong>, notamment en présence d'<strong>obésité</strong>, d'<strong>ascite</strong>, ou d'une <strong>masse indéterminée</strong> à la palpation.</p>"},{"i":"bd5922caa9aa","n":275,"o":"275-2","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic clinique d’une splénomégalie","q":"Quels sont les caractéristiques cliniques d'une rate palpable lors d'une splénomégalie ?","a":"<ul><li>Le <strong>bord antéro-interne est crénelé</strong>.</li><li>La <strong>percussion est mate</strong>.</li><li>Le <strong>contact lombaire est absent</strong>.</li></ul><p>Une splénomégalie peut être minime (1-2 cm sous le rebord), modérée, ou massive (<strong>> 10 cm</strong>, pouvant dépasser l'ombilic et occuper tout le flanc gauche).</p>"},{"i":"cdd32436204b","n":275,"o":"275-2","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic clinique d’une splénomégalie","q":"Quels sont les diagnostics différentiels d'une masse palpable de l'hypochondre gauche à ne pas confondre avec une splénomégalie ?","a":"<ul><li><strong>Hypertrophie du lobe hépatique gauche</strong>: masse en continuité avec le foie.</li><li><strong>Gros rein gauche</strong>: position postérieure, immobile à l'inspiration profonde, <strong>contact lombaire présent</strong>.</li><li><strong>Kyste ou tumeur de la queue du pancréas</strong>: non mobile à l'inspiration.</li><li><strong>Tumeur digestive ou mésentérique</strong> (notamment l'angle colique gauche): immobile, bord antérieur non crénelé.</li><li><strong>Tumeur surrénale gauche</strong>.</li><li><strong>Cancer gastrique</strong>: non mobile à l'inspiration.</li></ul>"},{"i":"16922cd9f57a","n":275,"o":"275-3","u":"Diagnostic positif","t":"Identifier les signes cliniques évocateurs d’une hépatopathie","q":"Devant un tableau de splénomégalie avec signes d'hépatopathie, quels signes cliniques évoquent spécifiquement une hypertension portale ?","a":"<p>Devant une splénomégalie avec signes d'hépatopathie, les signes cliniques évoquant spécifiquement une hypertension portale sont :</p><ul><li>La <strong>splénomégalie</strong> elle-même.</li><li>L'<strong>ascite</strong> et la <strong>circulation veineuse collatérale</strong> abdominale.</li><li>Les <strong>varices œsophagiennes</strong> (à rechercher par endoscopie œso-gastrique).</li></ul>"},{"i":"184f3e26cf2b","n":275,"o":"275-3","u":"Diagnostic positif","t":"Identifier les signes cliniques évocateurs d’une hépatopathie","q":"Devant une splénomégalie, quels sont les signes cliniques évocateurs d'une hépatopathie à rechercher spécifiquement pour orienter vers une cirrhose avec hypertension portale ?","a":"<p>Devant une splénomégalie, les signes cliniques évocateurs d'une hépatopathie qui orientent vers une cirrhose avec hypertension portale incluent :</p><ul><li>Un <strong>ictère</strong> conjonctival ou cutané.</li><li>Une <strong>hépatomégalie</strong>.</li><li>Une <strong>ascite</strong>.</li><li>Une <strong>circulation veineuse collatérale abdominale</strong>.</li><li>Des <strong>angiomes stellaires</strong> et une <strong>érythrose palmaire</strong>.</li><li>Un <strong>astérixis</strong> (en cas d'encéphalopathie hépatique).</li></ul>"},{"i":"cf7ba863490a","n":275,"o":"275-3","u":"Diagnostic positif","t":"Identifier les signes cliniques évocateurs d’une hépatopathie","q":"Devant une splénomégalie associée à des signes d'hépatopathie et d'hypertension portale, quelles sont les principales étiologies à évoquer ?","a":"<p>Devant une splénomégalie associée à des signes d'hépatopathie et d'hypertension portale, les étiologies à évoquer sont :</p><ul><li>La <strong>cirrhose</strong> (de loin la plus fréquente).</li><li>La <strong>thrombose de la veine porte</strong>.</li><li>Le <strong>syndrome de Budd-Chiari</strong>.</li><li>La <strong>schistosomiase</strong>.</li><li>L'<strong>insuffisance cardiaque droite</strong>.</li></ul>"},{"i":"56fb977142e4","n":275,"o":"275-4","u":"Identifier une urgence","t":"Identifier les signes d’un infarctus splénique","q":"Quels sont les signes cliniques clés d'un infarctus splénique ?","a":"<ul><li><strong>Fièvre</strong>, souvent modérée (<strong>38-38,5 °C</strong>).</li><li><strong>Douleurs</strong> localisées au flanc gauche, à l'hypochondre gauche, basithoracique gauche ou projetées vers la scapula gauche.</li><li>Possibilité d'un <strong>épanchement pleural réactionnel</strong>.</li></ul>"},{"i":"a909351c28ab","n":275,"o":"275-4","u":"Identifier une urgence","t":"Identifier les signes d’un infarctus splénique","q":"Comment doit être interprétée une splénomégalie douloureuse dans un contexte d'urgence ?","a":"<p>Une splénomégalie douloureuse doit être considérée comme un <strong>infarctus splénique</strong> jusqu'à preuve du contraire.</p>"},{"i":"f4bb23e9260b","n":275,"o":"275-4","u":"Identifier une urgence","t":"Identifier les signes d’un infarctus splénique","q":"Quel est l'examen d'imagerie de choix pour diagnostiquer un infarctus splénique et quels signes y rechercher ?","a":"<ul><li>La <strong>TDM abdominale</strong> est l'examen de choix, supérieure à l'échographie.</li><li>Il faut rechercher des <strong>plages hypodenses triangulaires périphériques</strong> au niveau de la rate.</li></ul>"},{"i":"686503223c75","n":275,"o":"275-5","u":"Examens complémentaires","t":"Connaître les principaux examens biologiques à réaliser en première intention devant une splénomégalie","q":"Dans quels contextes spécifiques des hémocultures et une recherche de paludisme sont-elles indiquées d'emblée devant une splénomégalie ?","a":"<p>Des <strong>hémocultures</strong> et une recherche de <strong>paludisme</strong> sont indiquées d'emblée devant une splénomégalie selon le contexte, notamment en présence de <strong>fièvre</strong> ou d'un <strong>séjour récent en zone d'endémie</strong>.</p>"},{"i":"937426db794c","n":275,"o":"275-5","u":"Examens complémentaires","t":"Connaître les principaux examens biologiques à réaliser en première intention devant une splénomégalie","q":"Quels sont les examens biologiques de première intention systématiquement réalisés devant une splénomégalie et quel est leur principal intérêt diagnostique ?","a":"<p>Devant une splénomégalie, les examens biologiques de première intention systématiquement réalisés sont :</p><ul><li>La <strong>Numération Formule Sanguine (NFS) avec frottis sanguin et réticulocytes</strong>, pour rechercher des hémopathies, des hémolyses ou des infections.</li><li>Le <strong>bilan hépatique</strong> (γ-GT, transaminases, PAL, TP), pour évaluer une hypertension portale ou une cytolyse hépatique.</li><li>L'<strong>électrophorèse des protides sériques (EPS/EPP)</strong>, pour rechercher un pic monoclonal, un bloc β-γ ou une hypergammaglobulinémie.</li><li>Les <strong>marqueurs d'hémolyse</strong> (bilirubine totale et libre, haptoglobine, LDH, test direct à l'antiglobuline), pour confirmer une hémolyse.</li><li>La <strong>CRP</strong>, pour rechercher un syndrome inflammatoire.</li><li>Un <strong>bilan de coagulation</strong>, pour évaluer une insuffisance hépatocellulaire ou un syndrome inflammatoire.</li></ul>"},{"i":"969113f16f53","n":275,"o":"275-5","u":"Examens complémentaires","t":"Connaître les principaux examens biologiques à réaliser en première intention devant une splénomégalie","q":"Quelles anomalies de la Numération Formule Sanguine (NFS) peuvent orienter le diagnostic devant une splénomégalie ?","a":"<p>Les anomalies de la NFS pouvant orienter le diagnostic devant une splénomégalie sont :</p><ul><li>Une <strong>thrombopénie</strong> (jusqu'à 50 G/L) ou une <strong>leucopénie</strong> (2-4 G/L), fréquentes.</li><li>Une <strong>anémie normocytaire</strong> parfois présente.</li><li>La présence de <strong>cellules anormales</strong> ou de <strong>corps de Howell-Joly</strong> (post-splénectomie) sur le frottis.</li><li>Une <strong>réticulocytose</strong> (100-180 G/L) suggérant une composante hémolytique.</li><li>Une <strong>polynucléose neutrophile</strong> orientant vers une infection bactérienne.</li><li>Une <strong>leucopénie</strong> orientant vers une infection virale, une fièvre typhoïde ou une brucellose.</li><li>Une <strong>hyperlymphocytose avec lymphocytes stimulés</strong> et angine fébrile suggérant un syndrome mononucléosique.</li><li>Une <strong>hyperlymphocytose chronique</strong> après 40-50 ans orientant vers un syndrome lymphoprolifératif.</li><li>Des <strong>cytopénies avec cellules anormales</strong> (blastes, tricholeucocytes) nécessitant un myélogramme.</li><li>Une <strong>anémie régénérative</strong> suggérant une hémolyse, avec nécessité d'un test direct à l'antiglobuline.</li><li>Une hémoglobine augmentée, une hyperleucocytose avec myélémie ou une hyperplaquettose chronique orientant vers une néoplasie myéloproliférative.</li></ul>"},{"i":"266c6f065f3e","n":275,"o":"275-8","u":"Étiologies","t":"Connaître les principales causes de splénomégalie (dont infections et hémopathies)","q":"Quelle est la cause la plus fréquente de splénomégalie dans le monde et en Europe ?","a":"<p>La cause la plus fréquente de splénomégalie dans le monde est le <strong>paludisme</strong>. En Europe, il s'agit de l'<strong>hypertension portale</strong>.</p>"},{"i":"4d92f593c574","n":275,"o":"275-8","u":"Étiologies","t":"Connaître les principales causes de splénomégalie (dont infections et hémopathies)","q":"Comment un tableau d'hémolyse se présente-t-il, et peut-il causer une splénomégalie ?","a":"<p>Oui, l'hémolyse chronique peut causer une splénomégalie. Le tableau d'hémolyse associe :</p><ul><li>Un <strong>ictère</strong></li><li>Des <strong>urines foncées</strong></li><li>Une <strong>anémie régénérative</strong></li><li>Une <strong>baisse de l'haptoglobine</strong></li><li>Une <strong>élévation de la bilirubine libre et des LDH</strong></li></ul><p>Il inclut les hémolyses chroniques corpusculaires et extra-corpusculaires.</p>"},{"i":"582bccb8275c","n":275,"o":"275-8","u":"Étiologies","t":"Connaître les principales causes de splénomégalie (dont infections et hémopathies)","q":"Quelles sont les principales causes d'hypertension portale pouvant entraîner une splénomégalie ?","a":"<p>Les principales causes d'hypertension portale pouvant entraîner une splénomégalie sont :</p><ul><li>La <strong>cirrhose</strong> (de loin la plus fréquente)</li><li>La <strong>thrombose de la veine porte</strong></li><li>Le <strong>syndrome de Budd-Chiari</strong></li><li>La compression tumorale intra-hépatique</li><li>L'hémochromatose</li><li>La sarcoïdose</li><li>La schistosomiase (bilharziose)</li><li>L'insuffisance cardiaque droite</li></ul>"},{"i":"caff397e93c6","n":275,"o":"275-8","u":"Étiologies","t":"Connaître les principales causes de splénomégalie (dont infections et hémopathies)","q":"Quelles sont les autres causes de splénomégalie, en dehors de l'hypertension portale, des infections, de l'hémolyse et des maladies systémiques ?","a":"<p>Les autres causes de splénomégalie sont :</p><ul><li>Les <strong>maladies de surcharge</strong> : maladie de Gaucher, maladie de Niemann-Pick</li><li>Les <strong>tumeurs et divers</strong> : métastase de tumeur solide, traumatisme, kystes, hémangiome</li></ul>"},{"i":"ce2c1a864e64","n":275,"o":"275-8","u":"Étiologies","t":"Connaître les principales causes de splénomégalie (dont infections et hémopathies)","q":"Quelles sont les principales infections à l'origine d'une splénomégalie ?","a":"<p>Les principales infections à l'origine d'une splénomégalie incluent :</p><ul><li><strong>Bactériennes</strong> : endocardite (maladie d'Osler), septicémies, tuberculose, fièvre typhoïde</li><li><strong>Virales</strong> : VIH, EBV, CMV, VZV (rare), hépatites virales</li><li><strong>Parasitaires</strong> : paludisme, leishmaniose viscérale (kala-azar), trypanosomiases</li><li><strong>Fongiques</strong> : Candida</li></ul>"},{"i":"d99f6168ac5e","n":275,"o":"275-8","u":"Étiologies","t":"Connaître les principales causes de splénomégalie (dont infections et hémopathies)","q":"Quelles maladies systémiques peuvent être à l'origine d'une splénomégalie ?","a":"<p>Les maladies systémiques pouvant être à l'origine d'une splénomégalie sont :</p><ul><li>Le <strong>lupus</strong></li><li>La <strong>sarcoïdose</strong></li><li>La <strong>polyarthrite inflammatoire</strong></li><li>La maladie périodique</li><li>Le <strong>syndrome de Felty</strong></li><li>La maladie de Still</li><li>La fièvre familiale méditerranéenne</li></ul>"},{"i":"9279fe78d795","n":275,"o":"275-9","u":"Étiologies","t":"Connaître les principales hémopathies responsables d’une splénomégalie","q":"Quelles hémopathies lymphoïdes peuvent être responsables d'une splénomégalie ?","a":"<p>Les hémopathies lymphoïdes pouvant être responsables d'une splénomégalie incluent :</p><ul><li>les <strong>lymphomes</strong> (maladie de Hodgkin et lymphomes non hodgkiniens),</li><li>les <strong>leucémies</strong> (leucémie lymphoïde chronique (LLC) et leucémie aiguë lymphoblastique (LAL)),</li><li>la <strong>maladie de Waldenström</strong>,</li><li>la <strong>leucémie à tricholeucocytes</strong>.</li></ul>"},{"i":"adbcae4e602d","n":275,"o":"275-9","u":"Étiologies","t":"Connaître les principales hémopathies responsables d’une splénomégalie","q":"Les syndromes myélodysplasiques (SMD) et les leucémies aiguës myéloïdes (LAM) sont-ils fréquemment associés à une splénomégalie ?","a":"<p>Non, les <strong>syndromes myélodysplasiques</strong> (SMD) et les <strong>leucémies aiguës myéloïdes</strong> (LAM) donnent <strong>rarement</strong> une splénomégalie. On retiendra plutôt la leucémie myélomonocytaire chronique (LMMC) et la leucémie aiguë lymphoblastique (LAL) pour les splénomégalies significatives.</p>"},{"i":"c1745beddb59","n":275,"o":"275-9","u":"Étiologies","t":"Connaître les principales hémopathies responsables d’une splénomégalie","q":"Le myélome multiple est-il une cause de splénomégalie ?","a":"<p>Non, le <strong>myélome multiple</strong> ne donne <strong>jamais</strong> de splénomégalie.</p>"},{"i":"fe8645ef030e","n":275,"o":"275-9","u":"Étiologies","t":"Connaître les principales hémopathies responsables d’une splénomégalie","q":"Quels syndromes myéloprolifératifs classiques sont responsables d'une splénomégalie ?","a":"<p>Les syndromes myéloprolifératifs classiques responsables d'une splénomégalie sont :</p><ul><li>la <strong>maladie de Vaquez</strong> (polyglobulie de Vaquez),</li><li>la <strong>thrombocytémie essentielle</strong>,</li><li>la <strong>myélofibrose primitive</strong> (également appelée splénomégalie myéloïde),</li><li>la <strong>leucémie myéloïde chronique</strong> (LMC).</li></ul>"}]};